{
  "status": "STABLE",
  "core_findings": [
    "All four categories show positive mean and 10th-percentile masked-position margins; sampled negatives beat positives in only 3.66–6.62% of measured positions.",
    "Electronics has the weakest sampled separation, while CDs_and_Vinyl has the strongest. Embedding scores of 0.5308–0.5631 indicate modest average directional similarity, not evidence of severe collapse."
  ],
  "key_implications": [
    "The model generally separates masked training targets from individual diagnostic negatives across all categories.",
    "Catalog embeddings retain directional variation, although this metric does not measure recommendation diversity.",
    "These training diagnostics do not establish validation HR@10 against 99 negatives or generalization performance."
  ],
  "evidence": {
    "headline_metrics": {
      "Electronics:pos_neg_margin_p10": 0.7269,
      "Electronics:pos_neg_neg_beats_pos_rate": 0.0662,
      "CDs_and_Vinyl:pos_neg_neg_beats_pos_rate": 0.0366,
      "Electronics:embedding_collapse_score": 0.5631
    },
    "brief_metric_read": {
      "Electronics:pos_neg_margin_p10": "Weakest lower-tail margin, still positive.",
      "Electronics:pos_neg_neg_beats_pos_rate": "Highest sampled ranking-error rate: 6.62%.",
      "CDs_and_Vinyl:pos_neg_neg_beats_pos_rate": "Lowest sampled ranking-error rate: 3.66%.",
      "Electronics:embedding_collapse_score": "Highest mean cosine similarity, approximately 0.1262."
    }
  }
}
